def replace_func(source, name, body):
    pattern=re.compile(r'^func '+re.escape(name)+r'\([^\n]*\)(?: -> [^\n:]+)?:\n.*?(?=^func |\Z)',re.M|re.S)
    match=pattern.search(source)
    if not match: raise AssertionError('Missing property phone function '+name)
    return source[:match.start()]+body.rstrip()+'\n\n'+source[match.end():]

def must(source, old, new):
    if old not in source: raise AssertionError('Property phone source drift: '+old[:120])
    return source.replace(old,new,1)

def patch_main(source):
    for name,body in MAIN_FUNCTIONS.items():
        if name=='_toggle_product_listing_local':
            if 'func _toggle_product_listing_local(' not in source:
                source+='\n'+body
            continue
        if name=='_phone_open_property_from_business':
            if 'func _phone_open_property_from_business(' not in source:
                source=must(source,'func _phone_business_select(property:String) -> void:',body+'\nfunc _phone_business_select(property:String) -> void:')
            continue
        source=replace_func(source,name,body)
    source=must(source,'func _build_products_app() -> void:', """func _build_products_app() -> void:
\tif neighborhood!=null and neighborhood.location_ops!=null and not neighborhood.location_ops.portfolio_property.is_empty():
\t\tneighborhood.location_ops.portfolio_stock_ui(phone_list)
\t\treturn
\t_build_products_local()

func _build_products_local() -> void:""".replace('\\t','\t'))
    source=must(source,'func _build_employees_app() -> void:', """func _build_employees_app() -> void:
\tif neighborhood!=null and neighborhood.location_ops!=null and not neighborhood.location_ops.portfolio_property.is_empty():
\t\tneighborhood.location_ops.portfolio_employees_ui(phone_list)
\t\treturn
\t_build_employees_legacy()

func _build_employees_legacy() -> void:""".replace('\\t','\t'))
    source=must(source,'if app_name in ["lights","business"]:app_name="budshop"\n\t_cancel_phone_gesture()', 'if app_name in ["lights","business"]:app_name="budshop"\n\tif neighborhood!=null and neighborhood.location_ops!=null and app_name=="realestate" and phone_current_app!="realestate" and phone_current_app not in ["employees","products"]:\n\t\tneighborhood.location_ops.portfolio_reset()\n\t_cancel_phone_gesture()')
    source=must(source,'phone_title.text = "Real Estate"','phone_title.text = "Properties"')
    source=must(source,'"Real Estate", "Properties, leases & payments", "realestate"','"Properties", "Manage property, staff, stock & bills", "realestate"')
    source=source.replace('neighborhood.location_ops.active_property().capitalize() if neighborhood!=null and neighborhood.location_ops!=null else "Operation"','neighborhood.location_ops.portfolio_property.capitalize() if neighborhood!=null and neighborhood.location_ops!=null and not neighborhood.location_ops.portfolio_property.is_empty() else "Operation"')
    return source

def patch_location(source):
    source=must(source,'var apartment_release_confirm := false','var apartment_release_confirm := false\n'+PORTFOLIO_VARIABLES.rstrip())
    source=must(source,'func real_estate_ui(parent:VBoxContainer) -> void:', 'func real_estate_ui(parent:VBoxContainer) -> void:\n\tportfolio_ui(parent)\n\treturn\n\n'+PORTFOLIO_ADDON+'\nfunc _legacy_real_estate_ui(parent:VBoxContainer) -> void:')
    return source

def patch_crew(source):
    source=replace_func(source,'role',CREW_ROLE)
    source=replace_func(source,'roster',CREW_ROSTER)
    return source
